const item = $input.first().json;
const body = item.body && typeof item.body === 'object' ? item.body : item;
const collection = String(body.collection || 'castuo_metrics').trim();
if (!collection || collection.includes('..') || collection.includes('/')) {
  return [{ json: { ok: false, error: 'collection inválida' } }];
}
const fields = body.fields && typeof body.fields === 'object' ? body.fields : {};
const base = String($env.DIRECTUS_URL || 'http://127.0.0.1:8055').replace(/\/+$/, '');
const url = `${base}/items/${encodeURIComponent(collection)}`;
return [{
  json: {
    ok: true,
    collection,
    directus_post_url: url,
    directus_body: { data: fields },
    hint: 'Insertar nodo HTTP Request POST entre este Code y Respond: url = directus_post_url, body JSON = directus_body, Authorization Bearer DIRECTUS_STATIC_TOKEN',
  },
}];
